package io.github.toolazytoname.xiaohei;
public final class SentenceTtsQueueTest {public static void main(String[] a){SentenceTtsQueue q=new SentenceTtsQueue();SentenceTtsQueue.Next x=q.replace("第一句。第二句！");if(x==null||!x.sentence.equals("第一句。"))throw new AssertionError();SentenceTtsQueue.Next y=q.complete(x.generation);if(y==null||!y.sentence.equals("第二句！"))throw new AssertionError();q.cancel();if(q.pending()!=0||q.complete(y.generation)!=null)throw new AssertionError();System.out.println("PASS sentence-tts first=immediate queued=1 cancel=clears stale_completion=ignore execution=0");}}
